import{_ as l,l as t,o as e,c as i,v as o,p as s,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Arellano 主权债务","description":"","frontmatter":{"title":"Arellano 主权债务","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/arellano-sovereign.md","filePath":"econ/arellano-sovereign.md","lastUpdated":1789023840000}'),A={name:"econ/arellano-sovereign.md"};function c(h,a,m,_,u,g){const n=t("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="arellano-主权债务" tabindex="-1">Arellano 主权债务 <a class="header-anchor" href="#arellano-主权债务" aria-label="Permalink to &quot;Arellano 主权债务&quot;">​</a></h1><div class="epigraph"><p>把 Eaton–Gersovitz 放进随机递归定量模型，才能同时谈违约频率、利差水平与债务/GDP——定性期权不够校准。</p><footer>—— Arellano, Default Risk and Income Fluctuations in Emerging Economies, AER 2008</footer></div><p><a href="/econ/eaton-gersovitz">上一课</a>给出违约期权装置。本课缺口是 <strong>Arellano 定量</strong>：匹配新兴市场的利差与违约。不重写惩罚的哲学，不把 \\(r-g\\) 会计提前当主课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EG 能解释利差随债与 \\(z\\) 升，但能否同时匹配：平均债不高、利差高、违约稀少却痛苦？Arellano：非完全可分的禀赋、违约时产出损失加排除，短期债，校准到阿根廷一类事实。发现：违约发生在衰退，利差波动大，债务水平被利差压在并不极高的位置。缺口是给 EG 一条可对矩的递归，而不是再讲一次声誉。</p><p><span class="marginnote">Arellano, <em>AER</em> 98(3), 2008, 690–712。Aguiar and Gopinath 的趋势冲击。Chatterjee and Eyigungor 的长期债。Hatchondo and Martinez。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态 \\((b,z)\\)，贝尔曼分履约值与违约值。债价由债权人零利润。算法：与 Aiyagari 同族——猜价格函数，解政府，更新价格。矩：违约频率、平均利差、债/GDP、贸易余额的周期。长期债：价格对未来违约更敏感，稀释激励（Borri、Hatchondo）。集体行动、谈判回收率改惩罚。</p>',8)),(e(),s(E,null,{default:r(()=>[p(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EG%5B%22EG%20%E6%9C%9F%E6%9D%83%22%5D%20--%3E%20QUAN%5B%22%E9%80%92%E5%BD%92%E5%AE%9A%E9%87%8F%22%5D%0A%20%20QUAN%20--%3E%20MOM%5B%22%E5%88%A9%E5%B7%AE%20%2F%20%E9%A2%91%E7%8E%87%20%2F%20%E5%80%BA%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20Z%5B%22%E8%A1%B0%E9%80%80%20z%22%5D%20--%3E%20DEF%5B%22%E8%BF%9D%E7%BA%A6%E5%8C%BA%22%5D%0A%20%20B%5B%22%E9%AB%98%20b%22%5D%20--%3E%20DEF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与全球周期：把债权人的随机贴现或 \\(\\phi\\) 写成全球因子，Arellano 的 \\(z\\) 就不只是本国 TFP。与银行：国内银行持有主权债，违约打 GK 净值（双环）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制仍是期权，定量上产出损失函数的凸性决定「坏年景才违约」。好年景借、坏年景紧——与数据中新兴市场的逆周期利差一致。趋势冲击（Aguiar–Gopinath）把「增长新闻」当成违约驱动，与新闻冲击课同构。短债滚动：像银行批发融资，对 \\(q\\) 的敏感超过基本面 \\(z\\) 的敏感。</p><p>不能匹配的矩推动模型扩充：长期债、风险厌恶债权人、政治。不要用一个 \\(z\\) 过程假装解释全部拉美史。</p><p><span class="marginnote">本课不评价某一笔重组方案。CDS 定价是模型的市场价格，不是本栏的交易课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 IMF 规划的全部条件性。本币债与通胀违约（稀释）下一课之后的主导课。发达经济的 \\(r-g\\) 可持续会计下一课：违约概率近零时 EG 的期权不是主约束。危机史模式再后。</p><p>后课默认：新兴市场利差可用 Arellano 类递归定量；矩驱动惩罚与债期限。下一课：当违约不是选项时，用 \\(r-g\\) 谈滚动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Arellano：EG 的定量递归，对利差、频率、债水平。</li><li>违约在衰退；利差压低稳态债务。</li><li>长期债、全球因子、银行持仓是标准扩充。</li><li>出处：Arellano, <em>AER</em> 2008。</li></ul>',10))])}const D=l(A,[["render",c]]);export{f as __pageData,D as default};
